"""Interview question bank, organized per career."""

QUESTIONS = {
    "ai-ml-engineer": [
        {"q": "Explain the bias-variance tradeoff and how you detect which one is hurting your model.", "a": "Bias = systematic error from overly simple models (underfitting); variance = sensitivity to training noise (overfitting). Diagnose via learning curves: high bias shows both train/val error high and close; high variance shows a widening gap. Remedies: more features/model capacity for bias; regularization, more data, simpler model for variance.", "difficulty": "beginner", "category": "ml", "skill": "machine-learning"},
        {"q": "How does backpropagation work?", "a": "Forward pass computes activations and loss. Backward pass applies the chain rule layer by layer to compute gradient of the loss w.r.t. every parameter, reusing intermediate results. Optimizers then update weights in the direction that reduces loss.", "difficulty": "intermediate", "category": "ml", "skill": "deep-learning"},
        {"q": "Why do transformers use self-attention instead of recurrence?", "a": "Self-attention lets every token attend to all others in O(1) sequential steps (parallelizable), capturing long-range dependencies directly, unlike RNNs whose sequential state limits context and prevents parallel training.", "difficulty": "advanced", "category": "ml", "skill": "transformers"},
        {"q": "What is RAG and when would you choose it over fine-tuning?", "a": "Retrieval-Augmented Generation injects retrieved documents into the prompt so the model answers from current/private knowledge. Prefer RAG for frequently changing or factual knowledge; prefer fine-tuning for style/format/task behavior with stable knowledge.", "difficulty": "advanced", "category": "ml", "skill": "llms-rag"},
        {"q": "Explain precision vs recall and when to optimize each.", "a": "Precision = TP/(TP+FP): how trustworthy positive predictions are. Recall = TP/(TP+FN): how many real positives you catch. Optimize precision when false positives are costly (spam filter), recall when false negatives are costly (cancer screening).", "difficulty": "beginner", "category": "ml", "skill": "scikit-learn"},
        {"q": "How do you handle data leakage?", "a": "Audit every feature for information unavailable at prediction time, fit scalers/encoders inside CV folds only, split time-series by time, and check suspiciously perfect feature importance. Prevention: strict pipeline discipline, not post-hoc detection.", "difficulty": "intermediate", "category": "ml", "skill": "feature-engineering"},
        {"q": "What is MLOps maturity? Describe a level-2 ML pipeline.", "a": "Level 2 = fully automated CI/CD/CT: new data or code triggers automated retraining pipelines, model registry gates deployments on eval metrics, monitoring triggers rollback/retrain on drift.", "difficulty": "advanced", "category": "devops", "skill": "mlops"},
        {"q": "PyTorch vs TensorFlow — how do you choose?", "a": "PyTorch dominates research and most new production stacks due to Pythonic ergonomics. TF/Keras remains strong in enterprise TFX/Serving ecosystems. Choose by team stack, deployment target and ecosystem needs.", "difficulty": "intermediate", "category": "programming", "skill": "pytorch"},
        {"q": "Design an ML system: YouTube video recommendations at scale.", "a": "Two-stage design: candidate generation (deep retrieval over millions of videos) then ranking (heavy scorer on hundreds of candidates) using watch-time weighted objectives. Discuss feature freshness, embedding serving, A/B infrastructure and feedback loops.", "difficulty": "advanced", "category": "system_design", "skill": "machine-learning"},
        {"q": "Write SQL to find the second-highest salary per department.", "a": "SELECT department, MAX(salary) FROM emp WHERE (department, salary) NOT IN (SELECT department, MAX(salary) FROM emp GROUP BY department) GROUP BY department; — or use DENSE_RANK() OVER (PARTITION BY department ORDER BY salary DESC) = 2.", "difficulty": "intermediate", "category": "databases", "skill": "sql"},
        {"q": "How does Docker help ML reproducibility?", "a": "Images pin OS, CUDA drivers, Python deps and code into one immutable artifact; the same image runs identically across laptop, CI and cluster, eliminating 'works on my machine' drift.", "difficulty": "beginner", "category": "cloud", "skill": "docker"},
        {"q": "Tell me about a time you had to explain a complex model to non-technical stakeholders.", "a": "STAR format answer: Situation (business decision pending), Task (translate model behavior), Action (analogies, visualizations, confidence intervals instead of jargon), Result (stakeholder approved launch). Prepare your own real example.", "difficulty": "beginner", "category": "behavioral", "skill": "communication"},
        {"q": "What is catastrophic forgetting and how do you mitigate it in LLM fine-tuning?", "a": "Fine-tuning on narrow data can erase general capabilities. Mitigations: LoRA/PEFT (small adapter weights), mixing replay data, lower learning rates, early stopping on held-out general benchmarks.", "difficulty": "advanced", "category": "ml", "skill": "llms-rag"},
        {"q": "How would you monitor a deployed model for drift?", "a": "Track input distributions (PSI/KL), prediction distribution shifts, and delayed ground-truth metrics. Alert on thresholds; automate retraining or shadow-mode evaluation when drift fires.", "difficulty": "advanced", "category": "devops", "skill": "mlops"},
    ],
    "data-scientist": [
        {"q": "Explain p-values to a product manager.", "a": "A p-value is the probability of seeing data at least this extreme if there were truly no effect. It's evidence against 'nothing happened', not the probability the hypothesis is true. Pair it with effect size and business impact.", "difficulty": "beginner", "category": "ml", "skill": "statistics"},
        {"q": "Design an A/B test for a new checkout flow.", "a": "Define the primary metric (conversion rate), guardrails (revenue, latency), compute sample size from baseline + MDE + power, randomize at user level, run full weekly cycles to avoid novelty effects, analyze with CUPED/variance reduction, decide on significance + practical significance.", "difficulty": "advanced", "category": "ml", "skill": "a-b-testing"},
        {"q": "Write a query for month-over-month revenue growth.", "a": "WITH monthly AS (SELECT DATE_TRUNC('month', order_date) m, SUM(amount) rev FROM orders GROUP BY 1) SELECT m, rev, 100.0*(rev-LAG(rev) OVER (ORDER BY m))/LAG(rev) OVER (ORDER BY m) AS growth_pct FROM monthly;", "difficulty": "intermediate", "category": "databases", "skill": "sql"},
        {"q": "How do you handle missing data?", "a": "First diagnose mechanism (MCAR/MAR/MNAR). Options: drop rows only if few and MCAR; impute median/mode/KNN/model-based for MAR; add missingness indicator flags; for MNAR involve domain knowledge. Never impute before splitting train/test.", "difficulty": "intermediate", "category": "ml", "skill": "eda"},
        {"q": "Your model has 99% accuracy but stakeholders are unhappy. What went wrong?", "a": "Likely class imbalance (fraud dataset where 99% are legit — predicting always-legit scores 99%). Reframe with precision/recall, PR-AUC, confusion matrix costs, and align metric with business cost asymmetry.", "difficulty": "beginner", "category": "ml", "skill": "machine-learning"},
        {"q": "What is Simpson's paradox and why does it matter?", "a": "An effect can reverse when aggregating across subgroups. Example: treatment looks better overall but worse within every age group. Always segment analysis by confounders before concluding.", "difficulty": "advanced", "category": "ml", "skill": "statistics"},
        {"q": "Explain cohort retention analysis and its key insight value.", "a": "Group users by signup period, track their repeat-activity curve over lifetime weeks. Reveals whether product changes improved long-run engagement vs vanity DAU numbers driven by acquisition spikes.", "difficulty": "intermediate", "category": "ml", "skill": "eda"},
        {"q": "Tableau vs Power BI — tradeoffs?", "a": "Tableau excels at flexible visual exploration and large analyst communities; Power BI wins on Microsoft-stack integration, pricing and enterprise governance. Know both concepts, tools are interchangeable.", "difficulty": "beginner", "category": "databases", "skill": "tableau"},
        {"q": "Describe a time your analysis changed a decision.", "a": "STAR: situation (contested roadmap bet), task (quantify impact), action (causal analysis with clear assumptions documented), result (team redirected resources; metric improved X%). Bring a specific personal story.", "difficulty": "beginner", "category": "behavioral", "skill": "communication"},
        {"q": "When is correlation enough vs needing causal inference?", "a": "Correlation suffices for forecasting stationary relationships under stable policy. You need causal methods (experiments, natural experiments, DiD, instrumental variables) when decisions intervene on the system and confounders lurk.", "difficulty": "advanced", "category": "ml", "skill": "statistics"},
        {"q": "What's the difference between supervised and unsupervised learning? Give business examples.", "a": "Supervised learns from labeled outcomes (churn yes/no, price regression). Unsupervised finds structure without labels (customer segmentation via k-means, anomaly detection). Most business value starts supervised; segmentation is the classic unsupervised win.", "difficulty": "beginner", "category": "ml", "skill": "machine-learning"},
        {"q": "How would you forecast demand for a seasonal product?", "a": "Decompose trend/seasonality/residuals; baseline with SARIMA or Prophet-style models; add exogenous regressors (promotions); validate with rolling-origin backtests using appropriate seasonal error metrics; quantify uncertainty intervals for inventory decisions.", "difficulty": "advanced", "category": "ml", "skill": "time-series"},
    ],
    "full-stack-developer": [
        {"q": "Explain the JavaScript event loop with microtasks vs macrotasks.", "a": "The call stack runs sync code; async callbacks queue as macrotasks (timers, I/O) while promise callbacks queue as microtasks that drain completely after each stack frame before the next macrotask. This ordering explains Promise.then firing before setTimeout.", "difficulty": "intermediate", "category": "programming", "skill": "javascript"},
        {"q": "What happens when you type a URL and press Enter?", "a": "DNS resolution -> TCP handshake -> TLS negotiation -> HTTP request -> server renders/responds -> browser parses HTML building DOM/CSSOM, executes JS, paints. Each stage offers caching/optimization hooks — interviewers probe depth here.", "difficulty": "intermediate", "category": "system_design", "skill": "system-design"},
        {"q": "Compare REST and GraphQL.", "a": "REST: resource URLs, HTTP verbs, cache-friendly, simple; risks over/under-fetching. GraphQL: single endpoint, client-specified shapes, fewer roundtrips; costs complexity in caching, N+1 resolution and query-cost control.", "difficulty": "intermediate", "category": "system_design", "skill": "rest-apis"},
        {"q": "How do you secure a JWT-based auth system?", "a": "Short-lived access tokens + rotating refresh tokens stored in httpOnly secure cookies, strong password hashing (bcrypt/argon2), rate limiting on login, audience/issuer validation, token revocation strategy on logout/compromise.", "difficulty": "advanced", "category": "system_design", "skill": "web-security"},
        {"q": "Explain React reconciliation and keys.", "a": "React diffs the new element tree against the previous one (reconciliation) applying minimal DOM updates. Keys give elements identity across renders so list items reorder efficiently instead of being destroyed/recreated — index keys break when lists mutate.", "difficulty": "intermediate", "category": "programming", "skill": "react"},
        {"q": "When does useEffect run and what causes infinite loops?", "a": "After commit when dependencies change. Infinite loops occur when the effect sets state referenced in its own dependency array, or creates a new object/array each render. Fix dependency arrays, use functional updates or memoize values.", "difficulty": "beginner", "category": "programming", "skill": "react"},
        {"q": "Design a URL shortener like bit.ly.", "a": "Key generation (base62 counter or hash + collision handling), read-heavy caching (Redis), 301 vs 302 redirects for analytics, DB sharding by hash, analytics pipeline async. Discuss capacity estimates explicitly.", "difficulty": "advanced", "category": "system_design", "skill": "system-design"},
        {"q": "SQL injection: demonstrate and prevent it.", "a": "Vulnerable: `\"SELECT * FROM users WHERE name='\"+input+\"'\"` lets input terminate the string and append logic. Prevent with parameterized queries/prepared statements, ORM parameter binding, least-privilege DB accounts; never string-concatenate SQL.", "difficulty": "intermediate", "category": "cybersecurity", "skill": "web-security"},
        {"q": "N+1 query problem — what and how to fix?", "a": "ORM lazily loads related rows per parent record causing 1+N queries. Fix with eager loading (JOIN/includes), batch loading (DataLoader pattern in GraphQL), or explicit query shaping; verify with query logging.", "difficulty": "intermediate", "category": "databases", "skill": "postgresql"},
        {"q": "CSS Flexbox vs Grid — when each?", "a": "Flexbox for one-dimensional layouts (rows OR columns, content-driven sizing). Grid for two-dimensional layouts with explicit tracks (page scaffolds). They compose: Grid page shell, Flex components inside.", "difficulty": "beginner", "category": "programming", "skill": "css"},
        {"q": "How would you improve Core Web Vitals of a slow React app?", "a": "Measure first (Lighthouse/RUM). Code-split routes, lazy-load below-fold, memoize expensive trees, virtualize long lists, compress images/WebP, preload critical assets, SSR/streaming for LCP, avoid layout shift with reserved dimensions.", "difficulty": "advanced", "category": "programming", "skill": "web-performance"},
        {"q": "Tell me about the hardest technical disagreement you've resolved.", "a": "STAR answer showing empathy + evidence: understand the other position, prototype both options cheaply, let data decide, document decision records. Avoid blaming teammates.", "difficulty": "beginner", "category": "behavioral", "skill": "communication"},
        {"q": "TypeScript generics — write a typed API response wrapper.", "a": "type ApiResponse<T> = { ok: true; data: T } | { ok: false; error: string }; function unwrap<T>(r: ApiResponse<T>): T { if (!r.ok) throw new Error(r.error); return r.data; } — generics keep call-site types precise.", "difficulty": "intermediate", "category": "programming", "skill": "typescript"},
        {"q": "How do WebSockets maintain connection and scale horizontally?", "a": "Upgrade handshake keeps TCP open for bidirectional frames; heartbeats detect dead peers. Horizontal scaling requires sticky sessions or a pub/sub backbone (Redis) broadcasting messages across node instances.", "difficulty": "advanced", "category": "system_design", "skill": "nodejs"},
    ],
    "devops-engineer": [
        {"q": "A pod is CrashLoopBackOff. Walk me through debugging.", "a": "`kubectl describe pod` events -> logs (`kubectl logs --previous`) for app errors -> check probes misconfiguration, OOMKilled limits, missing config/secrets, image tag existence. Escalate: exec in, port-forward locally. Fix root cause, not restart loops.", "difficulty": "intermediate", "category": "devops", "skill": "kubernetes"},
        {"q": "Explain Kubernetes Services vs Ingress.", "a": "Services give stable virtual IPs/DNS for pod sets (ClusterIP/NodePort/LB). Ingress is an L7 routing layer mapping host/path rules to services via controllers (nginx) enabling TLS termination and name-based virtual hosts.", "difficulty": "intermediate", "category": "devops", "skill": "kubernetes"},
        {"q": "Terraform state: why does it matter and how do you manage it safely?", "a": "State maps config to real resources; losing/corrupting it causes drift or recreation. Manage remotely (S3+DynamoDB locking / Terraform Cloud), never commit secrets, use workspaces/namespacing, plan-review-apply discipline, import existing infra deliberately.", "difficulty": "advanced", "category": "cloud", "skill": "terraform"},
        {"q": "Blue/green vs canary vs rolling deployments.", "a": "Blue/green: two full environments, instant switch, easy rollback, double cost. Canary: small traffic slice to new version with metric gating, gradual ramp. Rolling: replace instances incrementally, capacity-efficient but slower rollback. Choice depends on blast radius tolerance.", "difficulty": "intermediate", "category": "devops", "skill": "ci-cd"},
        {"q": "A production server's disk is filling up. Debug it live.", "a": "`df -h` confirm mount, `du -x` top offenders, check deleted-but-open files (`lsof +L1` — restart holding process), log rotation configs, docker system prune for images/volumes, inode exhaustion (`df -i`). Then fix root cause: rotation policies, alerts at 70%.", "difficulty": "intermediate", "category": "devops", "skill": "linux"},
        {"q": "What are SLOs/SLIs/error budgets and how do they drive engineering?", "a": "SLI = measured reliability dimension (latency p99, availability). SLO = target threshold. Error budget = allowed unreliability; spending it fast freezes features for reliability work — creating a shared business-engineering contract.", "difficulty": "advanced", "category": "system_design", "skill": "sre-practices"},
        {"q": "How does DNS resolution actually flow?", "a": "Stub resolver -> recursive resolver (ISP/8.8.8.8) -> root -> TLD (.com) -> authoritative nameserver, with TTL caching at each hop. Explain propagation myths, low-TTL migration strategies and CNAME flattening.", "difficulty": "beginner", "category": "devops", "skill": "networking"},
        {"q": "GitOps principles and benefits over push-based CD.", "a": "Declarative desired state in Git; an in-cluster controller continuously reconciles actual vs declared. Benefits: audit trail, drift detection, disaster recovery via re-sync, no CI credentials in cluster (pull model).", "difficulty": "advanced", "category": "devops", "skill": "gitops"},
        {"q": "Design observability for a microservices platform.", "a": "Three pillars: structured logs with trace IDs (Loki/ELK), metrics with RED/USE method (Prometheus), distributed tracing (OpenTelemetry -> Jaeger/Tempo). Correlate via exemplars; define actionable alerts on symptoms (SLO burn) not causes.", "difficulty": "advanced", "category": "system_design", "skill": "monitoring-observability"},
        {"q": "Secrets management: why not env vars in git?", "a": "Committed secrets leak forever (history, forks). Use dedicated stores (Vault, cloud secret managers, sealed-secrets) with rotation, least-privilege access, audit logging; inject at runtime via CSI/agent sidecars.", "difficulty": "intermediate", "category": "cybersecurity", "skill": "cloud-security"},
        {"q": "Tell me about a production incident you handled end-to-end.", "a": "STAR with ops specifics: detection (which alert), mitigation timeline (what stabilized first), comms cadence, root cause, postmortem action items that shipped. Emphasize blameless framing.", "difficulty": "beginner", "category": "behavioral", "skill": "communication"},
        {"q": "Ansible idempotency — what breaks it and how do you enforce it?", "a": "Idempotent modules converge state safely on reruns; raw shell/command tasks break it. Enforce with module-first choices, `creates:` guards, changed_when/failed_when, and Molecule tests for roles.", "difficulty": "intermediate", "category": "devops", "skill": "ansible"},
    ],
    "cybersecurity-analyst": [
        {"q": "Walk through the phases of an incident response lifecycle.", "a": "NIST: Preparation (playbooks, tooling) -> Detection & Analysis (triage, scope) -> Containment (short/long-term) -> Eradication (remove persistence) -> Recovery (restore, monitor) -> Lessons Learned (blameless postmortem feeding preparation).", "difficulty": "beginner", "category": "cybersecurity", "skill": "incident-response"},
        {"q": "You see impossible travel: login from New York then Moscow in 10 minutes. Next steps?", "a": "Verify VPN/geoIP false positives first; check MFA outcome, source IP reputation, user-agent consistency, concurrent sessions. Contain: kill sessions, force credential reset, hunt lateral movement from that identity, scope whether other accounts show similar patterns.", "difficulty": "intermediate", "category": "cybersecurity", "skill": "incident-response"},
        {"q": "Explain symmetric vs asymmetric cryptography and where TLS uses each.", "a": "Symmetric (AES) is fast for bulk data but needs shared keys; asymmetric (RSA/ECDH) solves key exchange but is slow. TLS handshakes use asymmetric crypto to authenticate + derive session keys, then switches to symmetric encryption.", "difficulty": "beginner", "category": "cybersecurity", "skill": "cryptography"},
        {"q": "What is XSS and how do the three types differ?", "a": "Injected scripts executing in victims' browsers: Stored (persisted server-side, hits everyone), Reflected (payload in request echoed back), DOM-based (client-side JS sinks). Defense: contextual output encoding, CSP, HttpOnly cookies, trusted-types.", "difficulty": "intermediate", "category": "cybersecurity", "skill": "owasp-top-10"},
        {"q": "How would you investigate a suspicious PowerShell execution alert?", "a": "Pull full command line + parent process tree, decode -enc/base64 payloads, check script-block logging, map behavior to ATT&CK (T1059.001), pivot on hashes/domains in threat intel, determine legitimacy (admin automation?) vs malicious (download cradle?), contain accordingly.", "difficulty": "advanced", "category": "cybersecurity", "skill": "siem"},
        {"q": "TCP three-way handshake — and how does SYN flood abuse it?", "a": "SYN -> SYN-ACK -> ACK establishes sequence numbers. SYN floods send SYNs without final ACKs exhausting half-open tables. Mitigations: SYN cookies, rate limiting, upstream scrubbing.", "difficulty": "beginner", "category": "cybersecurity", "skill": "networking"},
        {"q": "Difference between vulnerability assessment and penetration testing?", "a": "VA: breadth-first automated scanning, enumerates known weaknesses, low risk. PT: depth-first manual exploitation proving real-world impact chains, requires scope authorization. Mature programs run VA continuously, PT periodically.", "difficulty": "beginner", "category": "cybersecurity", "skill": "vulnerability-assessment"},
        {"q": "What is MITRE ATT&CK and how do you use it operationally?", "a": "A matrix of adversary tactics (goals) and techniques (methods). Uses: map detections to coverage gaps, structure threat intel, prioritize emulation tests, communicate risk in a common language.", "difficulty": "intermediate", "category": "cybersecurity", "skill": "threat-intelligence"},
        {"q": "Shared responsibility model: what's yours vs AWS's?", "a": "Provider secures OF the cloud (hardware, hypervisor, facility). Customer secures IN the cloud (IAM config, encryption, patching guest OS, network ACLs). Most cloud breaches stem from customer-side misconfigurations.", "difficulty": "beginner", "category": "cybersecurity", "skill": "cloud-security"},
        {"q": "How does Kerberos authentication work in Active Directory?", "a": "Client requests TGT from KDC (AS exchange), presents TGT to TGS for service tickets, service validates ticket. Attacks: Kerberoasting (request SPN tickets, crack offline), Pass-the-ticket, Golden tickets (krbtgt hash). Defend: gMSA accounts, long krbtgt rotation.", "difficulty": "advanced", "category": "cybersecurity", "skill": "iam"},
        {"q": "Describe handling a conflict during an incident when two teams disagree on containment.", "a": "STAR: incident pressure (situation), conflicting containment impact on revenue systems (task), facilitated rapid evidence-based decision meeting with clear risk articulation (action), contained threat with minimal downtime plus process improvement (result).", "difficulty": "beginner", "category": "behavioral", "skill": "communication"},
        {"q": "Write a Splunk query to count failed SSH logins by source IP in the last hour.", "a": "index=linux sourcetype=sshd \"Failed password\" earliest=-1h | rex \"from (?<src_ip>\\d+\\.\\d+\\.\\d+\\.\\d+)\" | stats count by src_ip | where count > 10 | sort -count — then correlate src_ip against threat intel.", "difficulty": "intermediate", "category": "cybersecurity", "skill": "siem"},
    ],
}
